//! Render the generated registry table.

use serde_json::Value;

use super::CODE_KEYS;

pub(super) fn render_markdown(registry: &Value) -> String {
    let version = registry
        .get("version")
        .and_then(Value::as_str)
        .unwrap_or("");
    let mut lines = vec![
        "# Indicator and Parameter Registry".to_owned(),
        String::new(),
        format!("- Version: `{version}`"),
        "- Source: [`indicators.json`](indicators.json)".to_owned(),
        "- Generated by `qr-governance registry --write`; do not edit by hand.".to_owned(),
        String::new(),
        "## Indicators".to_owned(),
        String::new(),
        "| ID | Code | Taxonomy | Role | Status | Claim |".to_owned(),
        "|---|---:|---|---|---|---|".to_owned(),
    ];
    for indicator in array(registry, "indicators") {
        lines.push(format!(
            "| `{}` | {} | {} | {} | {} | {} |",
            text(indicator, "id"),
            text(indicator, "code"),
            text(indicator, "taxonomy"),
            text(indicator, "role"),
            text(indicator, "status"),
            cell(text(indicator, "claim")),
        ));
    }
    lines.extend([
        String::new(),
        "## Events".to_owned(),
        String::new(),
        "| ID | Code | Type | Subtype | Sources | Indicator | Role | Status | Claim |".to_owned(),
        "|---|---:|---:|---:|---|---|---|---|---|".to_owned(),
    ]);
    for event in array(registry, "events") {
        let sources = event
            .get("sources")
            .and_then(Value::as_array)
            .map(|items| {
                items
                    .iter()
                    .map(Value::to_string)
                    .collect::<Vec<_>>()
                    .join("/")
            })
            .unwrap_or_else(|| text(event, "source"));
        lines.push(format!(
            "| `{}` | {} | {} | {} | {} | {} | {} | {} | {} |",
            text(event, "id"),
            text(event, "code"),
            text(event, "event_type"),
            text(event, "subtype"),
            sources,
            text(event, "indicator"),
            text(event, "role"),
            text(event, "status"),
            cell(text(event, "claim")),
        ));
    }
    lines.extend([
        String::new(),
        "## Parameters".to_owned(),
        String::new(),
        "| ID | Path | Default | Unit | Configurable | Affects | Status |".to_owned(),
        "|---|---|---|---|---|---|---|".to_owned(),
    ]);
    for parameter in array(registry, "parameters") {
        let default = parameter.get("default").cloned().unwrap_or(Value::Null);
        let affects = parameter
            .get("affects")
            .and_then(Value::as_array)
            .map(|items| {
                items
                    .iter()
                    .map(|value| value.as_str().unwrap_or("").to_owned())
                    .collect::<Vec<_>>()
                    .join(", ")
            })
            .unwrap_or_default();
        lines.push(format!(
            "| `{}` | `{}` | `{}` | {} | {} | {} | {} |",
            text(parameter, "id"),
            text(parameter, "path"),
            render_default(&default),
            text(parameter, "unit"),
            parameter
                .get("configurable")
                .and_then(Value::as_bool)
                .unwrap_or(false),
            affects,
            text(parameter, "status"),
        ));
    }
    lines.extend([String::new(), "## Codes".to_owned(), String::new()]);
    for key in CODE_KEYS {
        let mut entries: Vec<(&String, &Value)> = registry
            .get("codes")
            .and_then(|codes| codes.get(key))
            .and_then(Value::as_object)
            .map(|object| object.iter().collect())
            .unwrap_or_default();
        entries.sort_by_key(|(code, _)| code.parse::<i64>().unwrap_or(i64::MAX));
        let rendered = entries
            .iter()
            .map(|(code, label)| format!("{code} = {}", label.as_str().unwrap_or("")))
            .collect::<Vec<_>>()
            .join(", ");
        lines.push(format!("- **{key}**: {rendered}"));
    }
    lines.push(String::new());
    lines.join("\n")
}

pub(super) fn render_default(value: &Value) -> String {
    match value {
        Value::Null => "null".to_owned(),
        Value::Bool(value) => value.to_string(),
        Value::Number(value) => value.to_string(),
        Value::String(value) => serde_json::to_string(value).unwrap_or_default(),
        Value::Array(values) => format!(
            "[{}]",
            values
                .iter()
                .map(render_default)
                .collect::<Vec<_>>()
                .join(", ")
        ),
        Value::Object(values) => format!(
            "{{{}}}",
            values
                .iter()
                .map(|(key, value)| format!(
                    "{}: {}",
                    serde_json::to_string(key).unwrap_or_default(),
                    render_default(value)
                ))
                .collect::<Vec<_>>()
                .join(", ")
        ),
    }
}

fn array<'a>(registry: &'a Value, key: &str) -> &'a [Value] {
    registry
        .get(key)
        .and_then(Value::as_array)
        .map(Vec::as_slice)
        .unwrap_or_default()
}

fn text(value: &Value, key: &str) -> String {
    match value.get(key) {
        Some(Value::String(text)) => text.clone(),
        Some(value) => value.to_string(),
        None => String::new(),
    }
}

fn cell(value: String) -> String {
    value
        .split_whitespace()
        .collect::<Vec<_>>()
        .join(" ")
        .replace('|', "\\|")
}
